import sqlite3
import uuid
from datetime import datetime, timezone
from typing import Any, Optional

from app.models import TaskCreate


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _escape_like(term: str) -> str:
    return term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def row_to_dict(row: sqlite3.Row) -> dict[str, Any]:
    return dict(row)


def list_tasks(
    conn: sqlite3.Connection,
    search: Optional[str] = None,
    status: Optional[str] = None,
) -> list[dict[str, Any]]:
    query = "SELECT * FROM tasks WHERE 1=1"
    params: list[str] = []

    if search:
        escaped = _escape_like(search.lower())
        like = f"%{escaped}%"
        query += (
            " AND (LOWER(title) LIKE ? ESCAPE '\\' "
            "OR LOWER(COALESCE(description, '')) LIKE ? ESCAPE '\\')"
        )
        params += [like, like]

    if status:
        query += " AND status = ?"
        params.append(status)

    query += " ORDER BY created_at DESC"
    rows = conn.execute(query, params).fetchall()
    return [row_to_dict(r) for r in rows]


def get_task(conn: sqlite3.Connection, task_id: str) -> Optional[dict[str, Any]]:
    row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
    return row_to_dict(row) if row else None


def create_task(conn: sqlite3.Connection, data: TaskCreate) -> dict[str, Any]:
    task_id = str(uuid.uuid4())
    now = _now()
    conn.execute(
        "INSERT INTO tasks (id, title, description, status, created_at, updated_at) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (task_id, data.title, data.description, data.status, now, now),
    )
    conn.commit()
    result = get_task(conn, task_id)
    assert result is not None
    return result


def update_task(
    conn: sqlite3.Connection, task_id: str, fields: dict[str, Any]
) -> Optional[dict[str, Any]]:
    """Apply a partial update. `fields` should only contain explicitly-provided keys."""
    existing = get_task(conn, task_id)
    if existing is None:
        return None
    if not fields:
        return existing

    allowed = {"title", "description", "status"}
    set_clauses = []
    params: list[Any] = []
    for key, value in fields.items():
        if key not in allowed:
            continue
        set_clauses.append(f"{key} = ?")
        params.append(value)

    if not set_clauses:
        return existing

    set_clauses.append("updated_at = ?")
    params.append(_now())
    params.append(task_id)

    conn.execute(
        f"UPDATE tasks SET {', '.join(set_clauses)} WHERE id = ?",
        params,
    )
    conn.commit()
    return get_task(conn, task_id)


def delete_task(conn: sqlite3.Connection, task_id: str) -> bool:
    cursor = conn.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
    conn.commit()
    return cursor.rowcount > 0

