import sqlite3
from typing import Optional

from fastapi import APIRouter, Depends, HTTPException, Query, status as http_status

from app import repository
from app.database import get_db
from app.models import TaskCreate, TaskOut, TaskUpdate, VALID_STATUSES

router = APIRouter(prefix="/api/tasks", tags=["tasks"])


def _validate_status_param(status_param: Optional[str]) -> Optional[str]:
    if status_param is None:
        return None
    if status_param not in VALID_STATUSES:
        raise HTTPException(
            status_code=http_status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail=f"status must be one of {list(VALID_STATUSES)}",
        )
    return status_param


@router.get("", response_model=list[TaskOut])
def list_tasks(
    search: Optional[str] = Query(default=None),
    status: Optional[str] = Query(default=None),
    conn: sqlite3.Connection = Depends(get_db),
) -> list[dict]:
    validated_status = _validate_status_param(status)
    return repository.list_tasks(conn, search=search, status=validated_status)


@router.post("", response_model=TaskOut, status_code=http_status.HTTP_201_CREATED)
def create_task(payload: TaskCreate, conn: sqlite3.Connection = Depends(get_db)) -> dict:
    return repository.create_task(conn, payload)


@router.get("/{task_id}", response_model=TaskOut)
def get_task(task_id: str, conn: sqlite3.Connection = Depends(get_db)) -> dict:
    task = repository.get_task(conn, task_id)
    if task is None:
        raise HTTPException(status_code=http_status.HTTP_404_NOT_FOUND, detail="Task not found")
    return task


@router.patch("/{task_id}", response_model=TaskOut)
def update_task(
    task_id: str, payload: TaskUpdate, conn: sqlite3.Connection = Depends(get_db)
) -> dict:
    fields = payload.model_dump(exclude_unset=True)
    updated = repository.update_task(conn, task_id, fields)
    if updated is None:
        raise HTTPException(status_code=http_status.HTTP_404_NOT_FOUND, detail="Task not found")
    return updated


@router.delete("/{task_id}", status_code=http_status.HTTP_204_NO_CONTENT)
def delete_task(task_id: str, conn: sqlite3.Connection = Depends(get_db)) -> None:
    deleted = repository.delete_task(conn, task_id)
    if not deleted:
        raise HTTPException(status_code=http_status.HTTP_404_NOT_FOUND, detail="Task not found")

