import type { Task, TaskUpdateInput } from "../types";
import { TaskItem } from "./TaskItem";

export type ListState =
  | { kind: "loading" }
  | { kind: "error"; message: string }
  | { kind: "ready"; tasks: Task[] };

interface TaskListProps {
  state: ListState;
  onUpdate: (id: string, input: TaskUpdateInput) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}

export function TaskList({ state, onUpdate, onDelete }: TaskListProps) {
  if (state.kind === "loading") {
    return (
      <p role="status" className="status-message">
        Loading tasks…
      </p>
    );
  }

  if (state.kind === "error") {
    return (
      <p role="alert" className="status-message error">
        {state.message}
      </p>
    );
  }

  if (state.tasks.length === 0) {
    return <p className="status-message">No tasks yet — create one above.</p>;
  }

  return (
    <ul className="task-list" aria-label="Task list">
      {state.tasks.map((task) => (
        <TaskItem key={task.id} task={task} onUpdate={onUpdate} onDelete={onDelete} />
      ))}
    </ul>
  );
}

