:root {
  color-scheme: light;
  --color-bg: #f7f7f9;
  --color-surface: #ffffff;
  --color-border: #d8dae0;
  --color-text: #1f2430;
  --color-muted: #6b7280;
  --color-primary: #2952e3;
  --color-danger: #b3261e;
  --color-todo: #8a8f98;
  --color-doing: #b8860b;
  --color-done: #1e8e3e;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-text);
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1rem;
}

.app-header h1 {
  margin-bottom: 0.25rem;
}

.app-header p {
  margin-top: 0;
  color: var(--color-muted);
}

.task-form,
.filter-bar,
.task-item {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1rem;
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.filter-bar .form-field {
  flex: 1 1 200px;
}

.form-field {
  display: flex;
  flex-direction: column;
  margin-bottom: 0.75rem;
}

.form-field label {
  font-weight: 600;
  margin-bottom: 0.25rem;
}

input,
textarea,
select,
button {
  font: inherit;
}

input,
textarea,
select {
  padding: 0.5rem;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  width: 100%;
}

textarea {
  min-height: 4rem;
  resize: vertical;
}

button {
  padding: 0.5rem 1rem;
  border-radius: 6px;
  border: 1px solid var(--color-primary);
  background: var(--color-primary);
  color: white;
  cursor: pointer;
}

button[type="button"] {
  background: var(--color-surface);
  color: var(--color-primary);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.field-error {
  color: var(--color-danger);
  margin: 0.25rem 0 0;
  font-size: 0.9rem;
}

.status-message {
  padding: 1rem;
  text-align: center;
  color: var(--color-muted);
}

.status-message.error {
  color: var(--color-danger);
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.task-item {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.75rem;
  position: relative;
  padding-left: 1.5rem;
}

.status-dot {
  position: absolute;
  left: 0.75rem;
  top: 1.25rem;
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
}

.status-dot-todo {
  background: var(--color-todo);
}

.status-dot-doing {
  background: var(--color-doing);
}

.status-dot-done {
  background: var(--color-done);
}

.task-item-body {
  flex: 1 1 240px;
}

.task-item-body h3 {
  margin: 0 0 0.25rem;
}

.task-description {
  color: var(--color-muted);
  margin: 0 0 0.5rem;
}

.task-item-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

.task-edit-form {
  flex: 1 1 100%;
}

@media (max-width: 480px) {
  .app {
    padding: 0.5rem;
  }

  .filter-bar {
    flex-direction: column;
  }

  .task-item {
    flex-direction: column;
  }
}

