import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import { ApiError } from "../../api/client";
import { TaskForm } from "../TaskForm";

describe("TaskForm", () => {
  it("renders accessible title and description fields", () => {
    render(<TaskForm onCreate={vi.fn()} />);
    expect(screen.getByLabelText(/title/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/description/i)).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /add task/i })).toBeInTheDocument();
  });

  it("shows a validation error and does not submit for a whitespace-only title", async () => {
    const user = userEvent.setup();
    const onCreate = vi.fn().mockResolvedValue(undefined);
    render(<TaskForm onCreate={onCreate} />);

    await user.type(screen.getByLabelText(/title/i), "   ");
    await user.click(screen.getByRole("button", { name: /add task/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/title is required/i);
    expect(onCreate).not.toHaveBeenCalled();
  });

  it("shows a validation error for a title over 120 characters", async () => {
    const user = userEvent.setup();
    const onCreate = vi.fn().mockResolvedValue(undefined);
    render(<TaskForm onCreate={onCreate} />);

    await user.type(screen.getByLabelText(/title/i), "x".repeat(121));
    await user.click(screen.getByRole("button", { name: /add task/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/at most 120 characters/i);
    expect(onCreate).not.toHaveBeenCalled();
  });

  it("shows a validation error for a description over 500 characters", async () => {
    const user = userEvent.setup();
    const onCreate = vi.fn().mockResolvedValue(undefined);
    render(<TaskForm onCreate={onCreate} />);

    await user.type(screen.getByLabelText(/title/i), "Valid title");
    await user.type(screen.getByLabelText(/description/i), "y".repeat(501));
    await user.click(screen.getByRole("button", { name: /add task/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/at most 500 characters/i);
    expect(onCreate).not.toHaveBeenCalled();
  });

  it("submits trimmed values and clears the form on success", async () => {
    const user = userEvent.setup();
    const onCreate = vi.fn().mockResolvedValue(undefined);
    render(<TaskForm onCreate={onCreate} />);

    await user.type(screen.getByLabelText(/title/i), "  Buy milk  ");
    await user.type(screen.getByLabelText(/description/i), "  2% please  ");
    await user.click(screen.getByRole("button", { name: /add task/i }));

    await waitFor(() =>
      expect(onCreate).toHaveBeenCalledWith({ title: "Buy milk", description: "2% please" })
    );
    await waitFor(() => expect(screen.getByLabelText(/title/i)).toHaveValue(""));
  });

  it("shows a request-failure message when the backend rejects the request", async () => {
    const user = userEvent.setup();
    const onCreate = vi.fn().mockRejectedValue(new ApiError("Server is unavailable", 500));
    render(<TaskForm onCreate={onCreate} />);

    await user.type(screen.getByLabelText(/title/i), "Valid title");
    await user.click(screen.getByRole("button", { name: /add task/i }));

    expect(await screen.findByRole("alert")).toHaveTextContent(/server is unavailable/i);
  });
});

