import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import { FilterBar } from "../FilterBar";

describe("FilterBar", () => {
  it("renders accessible search and status filter controls", () => {
    render(
      <FilterBar search="" onSearchChange={vi.fn()} status="all" onStatusChange={vi.fn()} />
    );
    expect(screen.getByLabelText(/search tasks/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/filter by status/i)).toBeInTheDocument();
  });

  it("calls onSearchChange as the user types", async () => {
    const user = userEvent.setup();
    const onSearchChange = vi.fn();
    render(
      <FilterBar
        search=""
        onSearchChange={onSearchChange}
        status="all"
        onStatusChange={vi.fn()}
      />
    );

    await user.type(screen.getByLabelText(/search tasks/i), "milk");
    expect(onSearchChange).toHaveBeenCalled();
    expect(onSearchChange.mock.calls.map((c) => c[0]).join("")).toContain("k");
  });

  it("calls onStatusChange when a status is selected", async () => {
    const user = userEvent.setup();
    const onStatusChange = vi.fn();
    render(
      <FilterBar search="" onSearchChange={vi.fn()} status="all" onStatusChange={onStatusChange} />
    );

    await user.selectOptions(screen.getByLabelText(/filter by status/i), "doing");
    expect(onStatusChange).toHaveBeenCalledWith("doing");
  });

  it("offers all three statuses plus an all-statuses option", () => {
    render(
      <FilterBar search="" onSearchChange={vi.fn()} status="all" onStatusChange={vi.fn()} />
    );
    const select = screen.getByLabelText(/filter by status/i) as HTMLSelectElement;
    const optionValues = Array.from(select.options).map((o) => o.value);
    expect(optionValues).toEqual(["all", "todo", "doing", "done"]);
  });
});

