import { expect, test } from "@playwright/test";

test("create, search, move to done, and delete a task (desktop + mobile)", async ({ page }) => {
  const title = `E2E task ${Date.now()}`;

  // Mobile viewport first: the required controls must be usable at a small width (REQ-012).
  await page.setViewportSize({ width: 375, height: 700 });
  await page.goto("/");

  await expect(page.getByLabel(/title/i)).toBeVisible();
  await expect(page.getByLabel(/search tasks/i)).toBeVisible();
  await expect(page.getByRole("button", { name: /add task/i })).toBeVisible();

  await page.getByLabel(/^title$/i).fill(title);
  await page.getByLabel(/description/i).fill("Created by the Playwright e2e flow");
  await page.getByRole("button", { name: /add task/i }).click();

  const taskHeading = page.getByRole("heading", { name: title });
  await expect(taskHeading).toBeVisible();

  // Switch to a desktop viewport for the remainder of the flow.
  await page.setViewportSize({ width: 1280, height: 800 });

  // Search narrows the list down to the created task, without a page reload.
  await page.getByLabel(/search tasks/i).fill(title);
  await expect(taskHeading).toBeVisible();
  await expect(page.getByRole("listitem")).toHaveCount(1);

  // Move the task from todo to done via its status control.
  const statusSelect = page.getByLabel(new RegExp(`status for ${title}`, "i"));
  await expect(statusSelect).toHaveValue("todo");
  await statusSelect.selectOption("done");
  await expect(statusSelect).toHaveValue("done");

  // Delete the task and confirm it disappears from the list.
  await page.getByRole("button", { name: new RegExp(`delete ${title}`, "i") }).click();
  await expect(taskHeading).not.toBeVisible();
  await expect(page.getByText(/no tasks yet/i)).toBeVisible();
});

