1	import type { Task, TaskCreateInput, TaskStatus, TaskUpdateInput } from "../types";
2	
3	const API_BASE = "/api/tasks";
4	
5	export class ApiError extends Error {
6	  status: number;
7	
8	  constructor(message: string, status: number) {
9	    super(message);
10	    this.name = "ApiError";
11	    this.status = status;
12	  }
13	}
14	
15	async function parseErrorMessage(response: Response): Promise<string> {
16	  try {
17	    const body = await response.json();
18	    if (typeof body?.detail === "string") return body.detail;
19	    if (Array.isArray(body?.detail) && body.detail.length > 0) {
20	      const first = body.detail[0];
21	      return typeof first?.msg === "string" ? first.msg : JSON.stringify(body.detail);
22	    }
23	    return `Request failed with status ${response.status}`;
24	  } catch {
25	    return `Request failed with status ${response.status}`;
26	  }
27	}
28	
29	async function request<T>(input: string, init?: RequestInit): Promise<T> {
30	  let response: Response;
31	  try {
32	    response = await fetch(input, {
33	      headers: { "Content-Type": "application/json" },
34	      ...init,
35	    });
36	  } catch {
37	    throw new ApiError("Could not reach the server. Check your connection and try again.", 0);
38	  }
39	
40	  if (!response.ok) {
41	    const message = await parseErrorMessage(response);
42	    throw new ApiError(message, response.status);
43	  }
44	
45	  if (response.status === 204) {
46	    return undefined as T;
47	  }
48	  return (await response.json()) as T;
49	}
50	
51	export interface ListTasksParams {
52	  search?: string;
53	  status?: TaskStatus;
54	}
55	
56	export function listTasks(params: ListTasksParams = {}): Promise<Task[]> {
57	  const query = new URLSearchParams();
58	  if (params.search) query.set("search", params.search);
59	  if (params.status) query.set("status", params.status);
60	  const suffix = query.toString() ? `?${query.toString()}` : "";
61	  return request<Task[]>(`${API_BASE}${suffix}`);
62	}
63	
64	export function createTask(input: TaskCreateInput): Promise<Task> {
65	  return request<Task>(API_BASE, {
66	    method: "POST",
67	    body: JSON.stringify(input),
68	  });
69	}
70	
71	export function updateTask(id: string, input: TaskUpdateInput): Promise<Task> {
72	  return request<Task>(`${API_BASE}/${id}`, {
73	    method: "PATCH",
74	    body: JSON.stringify(input),
75	  });
76	}
77	
78	export function deleteTask(id: string): Promise<void> {
79	  return request<void>(`${API_BASE}/${id}`, { method: "DELETE" });
80	}
