1	import { useCallback, useEffect, useState } from "react";
2	import { ApiError, createTask, deleteTask, listTasks, updateTask } from "./api/client";
3	import { FilterBar } from "./components/FilterBar";
4	import type { StatusFilter } from "./components/FilterBar";
5	import { TaskForm } from "./components/TaskForm";
6	import { TaskList } from "./components/TaskList";
7	import type { ListState } from "./components/TaskList";
8	import type { TaskCreateInput, TaskUpdateInput } from "./types";
9	
10	const SEARCH_DEBOUNCE_MS = 300;
11	
12	export function App() {
13	  const [search, setSearch] = useState("");
14	  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
15	  const [listState, setListState] = useState<ListState>({ kind: "loading" });
16	
17	  const fetchTasks = useCallback(async (currentSearch: string, currentStatus: StatusFilter) => {
18	    setListState({ kind: "loading" });
19	    try {
20	      const tasks = await listTasks({
21	        search: currentSearch.trim() || undefined,
22	        status: currentStatus === "all" ? undefined : currentStatus,
23	      });
24	      setListState({ kind: "ready", tasks });
25	    } catch (err) {
26	      setListState({
27	        kind: "error",
28	        message:
29	          err instanceof ApiError
30	            ? err.message
31	            : "Could not load tasks. Check your connection and try again.",
32	      });
33	    }
34	  }, []);
35	
36	  useEffect(() => {
37	    const timer = setTimeout(() => {
38	      void fetchTasks(search, statusFilter);
39	    }, SEARCH_DEBOUNCE_MS);
40	    return () => clearTimeout(timer);
41	  }, [search, statusFilter, fetchTasks]);
42	
43	  async function handleCreate(input: TaskCreateInput) {
44	    await createTask(input);
45	    await fetchTasks(search, statusFilter);
46	  }
47	
48	  async function handleUpdate(id: string, input: TaskUpdateInput) {
49	    await updateTask(id, input);
50	    await fetchTasks(search, statusFilter);
51	  }
52	
53	  async function handleDelete(id: string) {
54	    await deleteTask(id);
55	    await fetchTasks(search, statusFilter);
56	  }
57	
58	  return (
59	    <div className="app">
60	      <header className="app-header">
61	        <h1>TaskFlow</h1>
62	        <p>Track your tasks from to-do through done.</p>
63	      </header>
64	
65	      <main>
66	        <TaskForm onCreate={handleCreate} />
67	        <FilterBar
68	          search={search}
69	          onSearchChange={setSearch}
70	          status={statusFilter}
71	          onStatusChange={setStatusFilter}
72	        />
73	        <TaskList state={listState} onUpdate={handleUpdate} onDelete={handleDelete} />
74	      </main>
75	    </div>
76	  );
77	}
