5	
6	interface FieldErrors {
7	  title?: string;
8	  description?: string;
9	}
10	
11	interface TaskFormProps {
12	  onCreate: (input: TaskCreateInput) => Promise<void>;
13	}
14	
15	export function TaskForm({ onCreate }: TaskFormProps) {
16	  const [title, setTitle] = useState("");
17	  const [description, setDescription] = useState("");
18	  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
19	  const [submitError, setSubmitError] = useState<string | null>(null);
20	  const [submitting, setSubmitting] = useState(false);
21	
22	  function validate(): FieldErrors {
23	    const errors: FieldErrors = {};
24	    const trimmedTitle = title.trim();
25	    if (!trimmedTitle) {
26	      errors.title = "Title is required.";
27	    } else if (trimmedTitle.length > 120) {
28	      errors.title = "Title must be at most 120 characters.";
29	    }
30	    if (description.trim().length > 500) {
31	      errors.description = "Description must be at most 500 characters.";
32	    }
33	    return errors;
34	  }
35	
36	  async function handleSubmit(event: FormEvent) {
37	    event.preventDefault();
38	    setSubmitError(null);
39	    const errors = validate();
40	    setFieldErrors(errors);
41	    if (Object.keys(errors).length > 0) return;
42	
43	    setSubmitting(true);
44	    try {
45	      await onCreate({
46	        title: title.trim(),
47	        description: description.trim() || undefined,
48	      });
49	      setTitle("");
50	      setDescription("");
51	      setFieldErrors({});
52	    } catch (err) {
53	      setSubmitError(
54	        err instanceof ApiError ? err.message : "Could not create the task. Please try again."
55	      );
56	    } finally {
57	      setSubmitting(false);
58	    }
59	  }
60	
61	  return (
62	    <form className="task-form" aria-label="Create task" onSubmit={handleSubmit} noValidate>
63	      <div className="form-field">
64	        <label htmlFor="task-title">Title</label>
65	        <input
66	          id="task-title"
67	          value={title}
68	          onChange={(e) => setTitle(e.target.value)}
69	          aria-invalid={Boolean(fieldErrors.title)}
70	          aria-describedby={fieldErrors.title ? "task-title-error" : undefined}
71	          maxLength={200}
72	        />
73	        {fieldErrors.title && (
74	          <p role="alert" id="task-title-error" className="field-error">
75	            {fieldErrors.title}
76	          </p>
77	        )}
78	      </div>
79	
80	      <div className="form-field">
81	        <label htmlFor="task-description">Description (optional)</label>
82	        <textarea
83	          id="task-description"
84	          value={description}
85	          onChange={(e) => setDescription(e.target.value)}
86	          aria-invalid={Boolean(fieldErrors.description)}
87	          aria-describedby={fieldErrors.description ? "task-description-error" : undefined}
88	        />
89	        {fieldErrors.description && (
90	          <p role="alert" id="task-description-error" className="field-error">
91	            {fieldErrors.description}
92	          </p>
93	        )}
94	      </div>
95	
96	      {submitError && (
97	        <p role="alert" className="field-error">
98	          {submitError}
99	        </p>
100	      )}
101	
102	      <button type="submit" disabled={submitting}>
103	        {submitting ? "Adding…" : "Add task"}
104	      </button>
105	    </form>
106	  );
107	}
