from typing import Literal

from pydantic import BaseModel, Field, field_validator

TaskStatus = Literal["todo", "doing", "done"]

VALID_STATUSES: tuple[TaskStatus, ...] = ("todo", "doing", "done")


def _validate_title(value: str) -> str:
    trimmed = value.strip()
    if not trimmed:
        raise ValueError("title must not be empty or whitespace-only")
    if len(trimmed) > 120:
        raise ValueError("title must be at most 120 characters")
    return trimmed


def _validate_description(value: str | None) -> str | None:
    if value is None:
        return None
    trimmed = value.strip()
    if len(trimmed) > 500:
        raise ValueError("description must be at most 500 characters")
    return trimmed or None


class TaskCreate(BaseModel):
    title: str
    description: str | None = Field(default=None)
    status: TaskStatus = "todo"

    @field_validator("title")
    @classmethod
    def validate_title(cls, v: str) -> str:
        return _validate_title(v)

    @field_validator("description")
    @classmethod
    def validate_description(cls, v: str | None) -> str | None:
        return _validate_description(v)


class TaskUpdate(BaseModel):
    """Partial update — only provided fields are validated and changed."""

    title: str | None = None
    description: str | None = None
    status: TaskStatus | None = None

    @field_validator("title")
    @classmethod
    def validate_title(cls, v: str | None) -> str | None:
        if v is None:
            return None
        return _validate_title(v)

    @field_validator("description")
    @classmethod
    def validate_description(cls, v: str | None) -> str | None:
        return _validate_description(v)

    def has_updates(self) -> bool:
        return self.title is not None or self.description is not None or self.status is not None


class TaskOut(BaseModel):
    id: str
    title: str
    description: str | None = None
    status: TaskStatus
    created_at: str
    updated_at: str

