import { useCallback, useEffect, useState } from "react";
import { ApiError, createTask, deleteTask, listTasks, updateTask } from "./api/client";
import { FilterBar } from "./components/FilterBar";
import type { StatusFilter } from "./components/FilterBar";
import { TaskForm } from "./components/TaskForm";
import { TaskList } from "./components/TaskList";
import type { ListState } from "./components/TaskList";
import type { TaskCreateInput, TaskUpdateInput } from "./types";

const SEARCH_DEBOUNCE_MS = 300;

export function App() {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [listState, setListState] = useState<ListState>({ kind: "loading" });

  const fetchTasks = useCallback(async (currentSearch: string, currentStatus: StatusFilter) => {
    setListState({ kind: "loading" });
    try {
      const tasks = await listTasks({
        search: currentSearch.trim() || undefined,
        status: currentStatus === "all" ? undefined : currentStatus,
      });
      setListState({ kind: "ready", tasks });
    } catch (err) {
      setListState({
        kind: "error",
        message:
          err instanceof ApiError
            ? err.message
            : "Could not load tasks. Check your connection and try again.",
      });
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      void fetchTasks(search, statusFilter);
    }, SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [search, statusFilter, fetchTasks]);

  async function handleCreate(input: TaskCreateInput) {
    await createTask(input);
    await fetchTasks(search, statusFilter);
  }

  async function handleUpdate(id: string, input: TaskUpdateInput) {
    await updateTask(id, input);
    await fetchTasks(search, statusFilter);
  }

  async function handleDelete(id: string) {
    await deleteTask(id);
    await fetchTasks(search, statusFilter);
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>TaskFlow</h1>
        <p>Track your tasks from to-do through done.</p>
      </header>

      <main>
        <TaskForm onCreate={handleCreate} />
        <FilterBar
          search={search}
          onSearchChange={setSearch}
          status={statusFilter}
          onStatusChange={setStatusFilter}
        />
        <TaskList state={listState} onUpdate={handleUpdate} onDelete={handleDelete} />
      </main>
    </div>
  );
}

